W = {
    (1, 6, 2): 2, (2, 6, 2): 2, (0, 6, 1): 1,
    (1, 3, 1): 1, (1, 4, 1): 1, (0, 3, 2): 1, (0, 4, 2): 1,
    (0, 2, 1): 1, (1, 2, 2): 1, (0, 0, 2): 1,
    (0, 1, 0): 1, (0, 5, 0): 0.5,
}

def pts(b):
    if b.last_col is None:
        return 0
